OLD='def _gen2_tick(root,ingest_fn=None,verdict_fn=None):\n    if ingest_fn is None:\n        from qseries_v2.oracle_predictive_discovery.opd_gen2_post_freeze_state_intake import ingest as ingest_fn\n    if verdict_fn is None:\n        from qseries_v2.oracle_predictive_discovery.opd_gen2_prove_or_kill_now import prove_or_kill as verdict_fn\n    sink=io.StringIO()\n    with contextlib.redirect_stdout(sink):\n        intake=ingest_fn(root,max_rows=50000)\n        verdict=verdict_fn(root)\n    best=verdict.get("best") or {}\n'
NEW='def _gen2_rows(root):\n    p=Path(root)/"runtime"/"predictive_data"/"opd_gen2_post_freeze_state_ledger.jsonl"\n    rows=[]\n    if not p.exists(): return rows\n    with p.open(encoding="utf-8") as f:\n        for line in f:\n            if not line.strip(): continue\n            try: rows.append(json.loads(line))\n            except Exception: pass\n    return rows\n\ndef _emit_gen2_visibility(rows):\n    for s in rows:\n        mids=list(s.get("matched_family_ids") or [])\n        print("[GEN2 STATE] ticker=%s horizon=%s formula_match=%s matched_family_ids=%s state_id=%s" % (\n            s.get("ticker"),s.get("horizon_seconds"),str(bool(mids)).upper(),",".join(mids) if mids else "NONE",s.get("state_id")),flush=True)\n\ndef _gen2_tick(root,ingest_fn=None,verdict_fn=None):\n    if ingest_fn is None:\n        from qseries_v2.oracle_predictive_discovery.opd_gen2_post_freeze_state_intake import ingest as ingest_fn\n    if verdict_fn is None:\n        from qseries_v2.oracle_predictive_discovery.opd_gen2_prove_or_kill_now import prove_or_kill as verdict_fn\n    before={x.get("state_id") for x in _gen2_rows(root)}\n    sink=io.StringIO()\n    with contextlib.redirect_stdout(sink):\n        intake=ingest_fn(root,max_rows=50000)\n        verdict=verdict_fn(root)\n    fresh=[x for x in _gen2_rows(root) if x.get("state_id") not in before]\n    _emit_gen2_visibility(fresh)\n    best=verdict.get("best") or {}\n'
TEST='import io,json,tempfile,contextlib\nfrom pathlib import Path\nimport qseries_v2.oracle_predictive_discovery.opd_044_continuous_prospective_worker as w\nwith tempfile.TemporaryDirectory() as d:\n r=Path(d);p=r/"runtime"/"predictive_data";p.mkdir(parents=True)\n rows=[{"state_id":"a","ticker":"KXBTC","horizon_seconds":300,"matched_family_ids":[]},{"state_id":"b","ticker":"KXETH","horizon_seconds":300,"matched_family_ids":["50ea5acf43d43f1ead2cc772"]}]\n (p/"opd_gen2_post_freeze_state_ledger.jsonl").write_text("".join(json.dumps(x)+"\\n" for x in rows),encoding="utf-8")\n assert len(w._gen2_rows(r))==2\n z=io.StringIO()\n with contextlib.redirect_stdout(z): w._emit_gen2_visibility(rows)\n out=z.getvalue()\n assert "ticker=KXBTC" in out and "formula_match=FALSE" in out and "matched_family_ids=NONE" in out\n assert "ticker=KXETH" in out and "formula_match=TRUE" in out and "50ea5acf43d43f1ead2cc772" in out\nassert w.execution_authority is False\nprint("[PASS] existing OPD-044 prints every newly admitted Gen2 state with exact frozen-family match visibility")\nprint("[PASS] visibility is read-only and does not alter candidate, thresholds, state admission, or outcomes")\nprint("[EXECUTION/PROBABILITY/DIRECTION/PUBLICATION] FALSE/FALSE/FALSE/FALSE")\n'
